// Reuse the App's pinned Unicode 15 tables and limits; never use the host ICU
// version for archive aliases. Generated files are not edited by hand.
import { createHash } from 'node:crypto';
import { readFileSync, readdirSync, mkdirSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { inflateSync } from 'node:zlib';

const worker = resolve(dirname(fileURLToPath(import.meta.url)), '..');
export function writeWorkshopData(root = worker) {
  const repo = resolve(root, '../..');
  const rules = readFileSync(resolve(repo, 'app/tool/pet-pack.rules.json'));
  const dart = readFileSync(resolve(repo, 'app/lib/pets/pet_unicode_data.g.dart'), 'utf8');
  const encoded = [...dart.split('const petUnicodeData =')[1].matchAll(/'([A-Za-z0-9+/=]+)'/g)].map(x => x[1]).join('');
  const hash = value => createHash('sha256').update(value).digest('hex');
  const expected = /petUnicodeDataSha256 = '([a-f0-9]{64})'/.exec(dart)?.[1];
  if (hash(inflateSync(Buffer.from(encoded, 'base64'))) !== expected) throw new Error('Invalid pinned Unicode data');
  const data = JSON.parse(rules);
  if (data.commonValidation.unicodeVersion !== '15.0.0') throw new Error('Review Unicode version change');
  const inputs = ['scripts/build-workshop-data.mjs', 'package-lock.json', 'tsconfig.json',
    ...readdirSync(resolve(root, 'src')).filter(name => name.startsWith('workshop-') || name === 'workshop.ts').map(name => `src/${name}`)]
    .sort().map(path => [path, hash(readFileSync(resolve(root, path)))]);
  const profile = hash(JSON.stringify({ inputs, rules: hash(rules), unicode: expected }));
  mkdirSync(resolve(root, 'src/generated'), { recursive: true });
  writeFileSync(resolve(root, 'src/generated/workshop-data.ts'),
    '// GENERATED by scripts/build-workshop-data.mjs. Do not edit.\n' +
    `export const PET_RULES_SHA256 = '${hash(rules)}';\n` +
    `export const WORKSHOP_VALIDATOR_PROFILE = '${profile}';\n` +
    `export const PET_LIMITS = ${JSON.stringify(data.limits)} as const;\n` +
    `export const UNICODE_DATA = '${encoded}';\n`);
}
if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) writeWorkshopData();
